import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});
const session: ChatSession = {
  sessionId: 'test-session',
  userId: 'user-1',
  entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
};
const provider: AIProvider = {
  // eslint-disable-next-line require-yield
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw 'string boom';
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
};

describe('ChatOrchestrator onError for non-Error rejections', () => {
  it('wraps a thrown string for onError and preserves it as cause while rethrowing it unchanged', async () => {
    let seenError: Error | undefined;
    const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {
      hooks: {onError: async (_session, error) => void (seenError = error)},
    });

    const rejection = await orchestrator.processMessage(session).then(
      () => undefined,
      (reason: unknown) => reason
    );

    expect({rejection, isError: seenError instanceof Error, message: seenError?.message, cause: seenError?.cause}).toEqual({
      rejection: 'string boom',
      isError: true,
      message: 'string boom',
      cause: 'string boom',
    });
  });
});
EOF
